/**
 * Station names in both languages. Apple Maps answers in the iPhone's language,
 * not the app's, so on a Japanese iPhone the English app would show 「渋谷駅」
 * (and the reverse). This list, Japanese ⇄ English, fills in the other one.
 *
 * Source: OpenStreetMap (railway stations in Japan with an English name),
 * © OpenStreetMap contributors, ODbL; credited in Data & licences.
 * Generated by scripts/build-station-names.py into lib/stationNamesData.ts.
 */
import { STATION_NAMES } from '@/lib/stationNamesData';

let jaToEn: Map<string, string> | null = null;
let enToJa: Map<string, string> | null = null;

/** For matching English names: no case, spaces, hyphens or macrons (Ōmiya = Omiya). */
function englishKey(name: string): string {
  return name.normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[\s\-‐'’.]/g, '').toLowerCase();
}

function load() {
  if (jaToEn && enToJa) return;
  jaToEn = new Map();
  enToJa = new Map();
  for (const line of STATION_NAMES.split('\n')) {
    const tab = line.indexOf('\t');
    if (tab <= 0) continue;
    const ja = line.slice(0, tab);
    const en = line.slice(tab + 1);
    if (!jaToEn.has(ja)) jaToEn.set(ja, en);
    const key = englishKey(en);
    if (!enToJa.has(key)) enToJa.set(key, ja);
  }
}

const JAPANESE = /[぀-ヿ㐀-鿿]/;

/**
 * Both names for a station name as Apple gave it (already without 駅 / Station):
 * the other language from the list, or the same name when it isn't listed.
 */
export function bilingualStationName(base: string): { name: string; nameJa: string } {
  load();
  if (JAPANESE.test(base)) return { nameJa: base, name: jaToEn!.get(base) ?? base };
  return { name: base, nameJa: enToJa!.get(englishKey(base)) ?? base };
}
